"use client";
import { useState } from "react";
import Link  from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Phone, Ambulance } from "lucide-react";
import { cn } from "@/lib/utils";
import { useRouter } from "next/navigation";
import { createAttendant, createDriver } from "@/app/features/auth/api/authApi";
import { CreateAttendantRequest, CreateDriverRequest } from "@/app/features/auth/requests/UsersRequests";
import { toast } from "@/components/ui/toast";

type Perfil = "telefonista" | "socorrista";

interface FormState {
  name: string;
  email: string;
  senha: string;
  confirmarSenha: string;
  telefone: string;
  perfil: Perfil;
  placa: string
}

export default function SignupPage() {
  const router = useRouter();


    // useEffect(() => {
    //   async function loadClients() {
    //     try {
    //       const data = await getUsersFromApi();
    //       const filteredClients = data.filter((user: User) => user.type == "Client");
    //       setClients(filteredClients);
    //     } catch (error) {
    //       console.error("Erro ao buscar clientes:", error);
    //     } finally {
    //       setIsLoading(false);
    //     }
    //   }

    //   loadClients();
    // }, []);

  const [form, setForm] = useState<FormState>({
    name: "",
    email: "",
    senha: "",
    confirmarSenha: "",
    telefone: "",
    perfil: "telefonista",
    placa: "",
  });
  const [erro, setErro] = useState<string | null>(null);

  function setField<K extends keyof FormState>(key: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setErro(null);

    if (form.senha !== form.confirmarSenha) {
      setErro("As senhas não coincidem.");
      return;
    }

    try {
      if (form.perfil === "telefonista") {
        const request: CreateAttendantRequest = {
          name: form.name,
          email: form.email,
          password: form.senha,
          phone: form.telefone,
        };
        await createAttendant(request);
      } else {
        const request: CreateDriverRequest = {
          name: form.name,
          email: form.email,
          password: form.senha,
          phone: form.telefone,
          vehicle: {
            plate: form.placa,
            latitude: 0,
            longitude: 0
          },
        };
        await createDriver(request);
      }
      
      toast.add({
        type: "info",
        description: ("Usuário criado com sucesso!"),
      });
      console.warn("Usuário criado com sucesso!");
      router.push(`/auth/login`);
      
    } catch (error) {  // pra pegar possiveis erros no server
      toast.add({
        type: "error",
        description: String(error),
      });
      console.warn(String(error));
    }
  }

  return (
    <div className="flex flex-col min-h-screen w-full bg-linear-to-b from-[#0d1117] to-[#170d0d] items-center justify-center">
      {/* Container */}
      <div className="w-100 h-fit rounded-2xl border border-white/20 bg-[#1c2330] flex flex-col p-4 gap-4">
        <div className="flex flex-col gap-2">
          <h1 className="text-xl font-normal text-white">Cadastro</h1>
          <p className="text-sm text-white/60">
            Crie a sua conta para continuar
          </p>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col gap-1 text-xs">

          <Field label="Nome">
            <Input
              type="name"
              placeholder="Ex: Allan"
              value={form.name}
              onChange={(e) => setField("name", e.target.value)}
              className={inputClasses}
              required
            />
          </Field>

          <Field label="Email">
            <Input
              type="email"
              placeholder="Ex: allanshinhama@gmail.com"
              value={form.email}
              onChange={(e) => setField("email", e.target.value)}
              className={inputClasses}
              required
            />
          </Field>

          <Field label="Senha">
            <Input
              type="password"
              placeholder="Ex: allan123"
              value={form.senha}
              onChange={(e) => setField("senha", e.target.value)}
              className={inputClasses}
              required
            />
          </Field>

          <Field label="Confirme a Senha">
            <Input
              type="password"
              placeholder="Ex: allan123"
              value={form.confirmarSenha}
              onChange={(e) => setField("confirmarSenha", e.target.value)}
              className={inputClasses}
              required
            />
          </Field>

          <Field label="Telefone">
            <Input
              type="tel"
              placeholder="Ex: 14981826224"
              value={form.telefone}
              onChange={(e) => setField("telefone", e.target.value)}
              className={inputClasses}
              required
            />
          </Field>

          <div className="flex flex-col gap-2">
            <Label className="text-base font-normal text-white/50">
              Cadastrar como
            </Label>
            <div className="flex h-12 gap-2">
              <PerfilOption
                icon={Phone}
                label="Telefonista"
                selected={form.perfil === "telefonista"}
                onClick={() => setField("perfil", "telefonista")}
              />
              <PerfilOption
                icon={Ambulance}
                label="Ambulância"
                selected={form.perfil === "socorrista"}
                onClick={() => setField("perfil", "socorrista")}
              />
            </div>
          </div>
          
          {form.perfil === "socorrista" && (
            <div className="flex w-full h-10">
              <Input
                placeholder="Placa do Veículo"
                value={form.placa}
                onChange={(e) => setField("placa", e.target.value)}
                className={inputClasses}
                required
              />
            </div>              
          )}
          {erro && <p className="text-sm text-[#f64444]">{erro}</p>}

          <Button
            type="submit"
            className="mt-2.5 h-[40px] w-full rounded-[10px] bg-[#f93a3a] text-lg font-semibold text-white hover:bg-[#e13333]"
          >
            Cadastrar
          </Button>

          <div className="flex w-full justify-end">
            <p className="text-center text-[10px] text-white">
              Clique aqui para{" "}
              <Link href="/auth/login" className="text-[#f64444] underline">
                Logar
              </Link>
            </p>            
          </div>

        </form>
      </div>
      <span className="my-2">
        <p className="text-white/50 text-[8px]">
          Secretaria da Saúde de Marília — Uso restrito a funcionários autorizados
        </p>
      </span>
    </div>
  );
}

const inputClasses =
  "h-auto text-xs rounded-[10px] border border-[#30363d] bg-[#1c2330] px-5 py-[8px] text-xs text-white placeholder:text-white/50 focus-visible:ring-1 focus-visible:ring-white/50";

function Field({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex flex-col gap-1">
      <Label className="text-base font-normal text-white/50">{label}</Label>
      {children}
    </div>
  );
}

function PerfilOption({
  icon: Icon,
  label,
  selected,
  onClick,
}: {
  icon: typeof Phone;
  label: string;
  selected: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "flex flex-1 items-center justify-center gap-[15px] rounded-xl border border-[#30363d] px-5 py-[5px] transition-colors",
        selected ? "bg-white text-black" : "bg-[#1c2330] text-white/50",
      )}
    >
      <Icon className="h-[17px] w-[17px]" />
      <span className="text-base">{label}</span>
    </button>
  );
}
